 36	// Derive a per-key cuDF cast type so independently-planned senders always hash identically.
 37	// Different planners may bind the same logical column to different native widths (e.g. INT32 vs
 38	// INT64). cuDF's murmur3 hashes bytes, not values, so without normalization matching keys land in
 39	// different partitions and groups are silently split.
 40	//
 41	// Rules:
 42	//   TINYINT / SMALLINT / INTEGER → INT64   (all sub-64-bit integers → canonical 64-bit)
 43	//   BIGINT / BOOLEAN / VARCHAR / DOUBLE → EMPTY (already canonical; hash as-is)
 44	//   FLOAT                        → FLOAT64 (sub-64-bit float → canonical 64-bit)
 45	//   DECIMAL (any precision/scale) → FLOAT64 (normalized floating representation)
 46	//   anything else                → throw
 47	cudf::data_type derive_key_cast_type(const sirius::logical_type& t)
 48	{
 49	  switch (t.id()) {
 50	    case sirius::type_id::TINYINT:
 51	    case sirius::type_id::SMALLINT:
 52	    case sirius::type_id::INTEGER: return cudf::data_type{cudf::type_id::INT64};
 53	    case sirius::type_id::BIGINT:
 54	    case sirius::type_id::BOOLEAN:
 55	    case sirius::type_id::VARCHAR:
 56	    case sirius::type_id::DOUBLE: return cudf::data_type{cudf::type_id::EMPTY};
 57	    case sirius::type_id::FLOAT:
 58	    case sirius::type_id::DECIMAL: return cudf::data_type{cudf::type_id::FLOAT64};
 59	    default:
 60	      throw sirius::invalid_input_exception(
 61	        "streaming_fragment: unsupported partition key type — only integer, boolean, varchar, "
 62	        "float, and decimal columns may be used as hash partition keys");
 63	  }
 64	}
 65	
 66	// Fill partition_spec::key_cast_types when the caller left it empty.
 67	// No-op when the caller supplied their own cast types.
 68	void normalize_key_cast_types(op::partition_spec& spec,
 69	                              const duckdb::vector<sirius::logical_type>& output_types)
 70	{
 71	  if (!spec.key_cast_types.empty()) { return; }
 72	  spec.key_cast_types.reserve(spec.key_columns.size());
 73	  for (int key : spec.key_columns) {
 74	    // The sink validates key ranges too, but it is constructed after this runs — so an
 75	    // out-of-range or negative key would index output_types out of bounds first.
 76	    if (key < 0 || static_cast<std::size_t>(key) >= output_types.size()) {
 77	      throw sirius::invalid_input_exception("streaming_fragment: partition key column " +
 78	                                            std::to_string(key) + " is out of range for a " +
 79	                                            std::to_string(output_types.size()) + "-column output");
 80	    }
 81	    spec.key_cast_types.push_back(derive_key_cast_type(output_types[key]));
 82	  }
 83	}
