 87	streaming_fragment::streaming_fragment(duckdb::ClientContext& context, fragment_spec spec)
 88	  : _context(context), _spec(std::move(spec))
 89	{
 90	  if (!_spec.plan_source) {
 91	    throw sirius::invalid_input_exception("streaming_fragment: a plan source is required");
 92	  }
 93	  if (_spec.outputs.empty()) {
 94	    throw sirius::invalid_input_exception(
 95	      "streaming_fragment: a fragment must declare at least one output stream");
 96	  }
 97	  if (_spec.outputs.size() > 1 && !_spec.partitioning.has_value()) {
 98	    throw sirius::invalid_input_exception(
 99	      "streaming_fragment: " + std::to_string(_spec.outputs.size()) +
100	      " output streams need a partition spec; a gather fragment has exactly one");
101	  }
102	
103	  // Repositories escape data_repository_manager_ cleanup so sender output outlives this fragment.
104	  for (const auto& [id, _] : _spec.inputs) {
105	    _input_repos[id] = std::make_shared<cucascade::shared_data_repository>();
106	  }
107	  for (auto id : _spec.outputs) {
108	    if (_output_repos.count(id) != 0) {
109	      throw sirius::invalid_input_exception("streaming_fragment: duplicate output stream id " +
110	                                            std::to_string(id));
111	    }
112	    _output_repos[id] = std::make_shared<cucascade::shared_data_repository>();
113	  }
114	}
