116	streaming_fragment::~streaming_fragment()
117	{
118	  // Drop only the ids this fragment declared. clear() would wipe the whole per-connection
119	  // catalog, including a peer fragment's declarations; swallow in dtor.
120	  try {
121	    auto catalog = catalog_for(_context);
122	    for (const auto& [id, _] : _spec.inputs) {
123	      catalog->erase(id);
124	    }
125	  } catch (...) {  // NOLINT(bugprone-empty-catch)
126	  }
127	}
