129	void streaming_fragment::build(sirius::query_id_t query_id)
130	{
131	  if (_built) { throw sirius::invalid_input_exception("streaming_fragment: already built"); }
132	
133	  auto catalog = catalog_for(_context);
134	  // Same reason as the destructor: erase our own ids so a rebuild is idempotent without
135	  // discarding declarations that belong to another fragment on this connection.
136	  for (const auto& [id, _] : _spec.inputs) {
137	    catalog->erase(id);
138	  }
139	
140	  // Declare before planning: bind resolves schema; create_plan reads repo + senders.
141	  for (const auto& [id, input] : _spec.inputs) {
142	    catalog->declare(id,
143	                     stream_input_binding{input.names,
144	                                          input.types,
145	                                          _input_repos.at(id),
146	                                          input.expected_senders,
147	                                          input.estimated_rows,
148	                                          nullptr});
149	  }
150	
151	  auto logical_plan = _spec.plan_source(_context);
152	  if (!logical_plan) {
153	    throw sirius::invalid_input_exception("streaming_fragment: plan source produced no plan");
154	  }
155	
156	  sirius::planner::sirius_physical_plan_generator generator(_context);
157	  auto subtree = generator.create_plan(std::move(logical_plan));
158	
159	  // STREAMING_SINK is a normal unary: subtree in children[] (unlike RESULT_COLLECTOR).
160	  auto types       = subtree->types;
161	  auto cardinality = subtree->estimated_cardinality;
162	  _sink_types      = types;  // snapshot before types is moved into the sink constructor
163	
164	  std::vector<std::shared_ptr<cucascade::shared_data_repository>> sink_repos;
165	  sink_repos.reserve(_spec.outputs.size());
166	  for (auto id : _spec.outputs) {
167	    sink_repos.push_back(_output_repos.at(id));
168	  }
169	
170	  duckdb::unique_ptr<op::sirius_physical_streaming_sink> sink;
171	  if (_spec.partitioning.has_value()) {
172	    normalize_key_cast_types(*_spec.partitioning, types);
173	    sink = duckdb::make_uniq<op::sirius_physical_streaming_sink>(
174	      std::move(types), cardinality, std::move(sink_repos), *_spec.partitioning);
175	  } else {
176	    sink = duckdb::make_uniq<op::sirius_physical_streaming_sink>(
177	      std::move(types), cardinality, sink_repos.front());
178	  }
179	  sink->children.push_back(std::move(subtree));
180	
181	  // Engine owns the plan; fragment owns the engine so the sink stays pullable after run().
182	  _iface = std::make_unique<sirius::sirius_interface>(
183	    _context, _spec.query_label.value_or(kFragmentQueryLabel), _spec.session_label);
184	  _engine = std::make_unique<sirius::sirius_engine>(_context, *_iface, query_id);
185	  _engine->initialize(std::move(sink));
186	
187	  auto& sink_ref = _engine->sirius_physical_plan->Cast<op::sirius_physical_streaming_sink>();
188	
189	  _session.add_sink(_spec.outputs, sink_ref);
190	  for (const auto& [id, _] : _spec.inputs) {
191	    auto* built = catalog->get(id).built;
192	    if (built == nullptr) {
193	      // Declared but unread = hang; fail loudly.
194	      throw sirius::invalid_input_exception("streaming_fragment: input stream " +
195	                                            std::to_string(id) +
196	                                            " was declared but the plan does not read it");
197	    }
198	    _session.add_source(id, *built);
199	  }
200	
201	  _built = true;
202	}
203	
204	void streaming_fragment::run()
205	{
206	  if (!_built) {
207	    throw sirius::invalid_input_exception("streaming_fragment: build() must run before run()");
208	  }
209	
210	  try {
211	    // Shared query window (don't open a second StandaloneQueryScope): a new window resets
212	    // task_creator / scan manager that build() populated → zero tasks, empty output, no error.
213	    _engine->execute();
214	  } catch (...) {
215	    // Poison every output before unwinding: otherwise the streams are neither closed nor
216	    // failed, so a peer parked in wait() blocks forever with no error anywhere. fail_output is
217	    // idempotent (first-failure-wins), so this stays safe even when a caller (e.g.
218	    // sirius::ffi::Fragment::run()) also poisons the same outputs itself.
219	    auto const cause = std::current_exception();
220	    for (auto id : _spec.outputs) {
221	      try {
222	        _session.fail_output(id, cause);
223	      } catch (...) {  // NOLINT(bugprone-empty-catch)
224	      }
225	    }
226	    throw;
227	  }
228	}
