230	const duckdb::vector<sirius::logical_type>& streaming_fragment::sink_types() const
231	{
232	  if (!_built) {
233	    throw sirius::invalid_input_exception("streaming_fragment: sink_types() called before build()");
234	  }
235	  return _sink_types;
236	}
