238	const std::shared_ptr<cucascade::shared_data_repository>& streaming_fragment::input_repository(
239	  stream_id_t id) const
240	{
241	  auto it = _input_repos.find(id);
242	  if (it == _input_repos.end()) {
243	    throw sirius::invalid_input_exception("streaming_fragment: no input stream with id " +
244	                                          std::to_string(id));
245	  }
246	  return it->second;
247	}
