249	const std::shared_ptr<cucascade::shared_data_repository>& streaming_fragment::output_repository(
250	  stream_id_t id) const
251	{
252	  auto it = _output_repos.find(id);
253	  if (it == _output_repos.end()) {
254	    throw sirius::invalid_input_exception("streaming_fragment: no output stream with id " +
255	                                          std::to_string(id));
256	  }
257	  return it->second;
258	}
