 33	static std::string tier_to_string(cucascade::memory::Tier tier)
 34	{
 35	  switch (tier) {
 36	    case cucascade::memory::Tier::GPU: return "GPU";
 37	    case cucascade::memory::Tier::HOST: return "HOST";
 38	    case cucascade::memory::Tier::DISK: return "DISK";
 39	    default: return "UNKNOWN";
 40	  }
 41	}
