 43	downgrade_executor::downgrade_executor(
 44	  exec::downgrade_executor_config config,
 45	  sirius::data::data_repository_manager_registry& data_repo_registry,
 46	  cucascade::memory::memory_space_id space_id,
 47	  cucascade::memory::memory_space* memory_space,
 48	  sirius::memory::sirius_memory_reservation_manager& reservation_manager,
 49	  sirius::exec::multi_index_priority_queue<sirius::parallel::itask>* pipeline_task_queue)
 50	  : _config(std::move(config)),
 51	    _data_repo_registry(data_repo_registry),
 52	    _space_id(space_id),
 53	    _memory_space(memory_space),
 54	    _source_label(tier_to_string(space_id.tier) + ":" + std::to_string(space_id.device_id)),
 55	    _reservation_manager(reservation_manager),
 56	    _pipeline_task_queue(pipeline_task_queue)
 57	{
 58	}
