 62	void downgrade_executor::start()
 63	{
 64	  bool expected = false;
 65	  if (!_running.compare_exchange_strong(expected, true)) { return; }
 66	
 67	  // HOST/DISK tier memory_spaces return device_id == -1; passing that to
 68	  // rmm::cuda_device_id or cudaSetDevice fails with cudaErrorInvalidDevice.
 69	  // Default the stream pool to GPU 0 for non-GPU tiers and skip per-thread
 70	  // CUDA binding entirely (the stream is ordering metadata; host/disk work
 71	  // is CPU-side).
 72	  {
 73	    int device_id = 0;
 74	    if (_space_id.tier == cucascade::memory::Tier::GPU && _memory_space) {
 75	      device_id = _memory_space->get_device_id();
 76	    }
 77	    _stream_pool = std::make_unique<cucascade::memory::exclusive_stream_pool>(
 78	      rmm::cuda_device_id{device_id}, _config.thread_pool.num_threads);
 79	  }
 80	
 81	  _request_queue.reactivate();
 82	
 83	  absl::AnyInvocable<void() noexcept> per_thread_init = nullptr;
 84	  if (_memory_space && _space_id.tier == cucascade::memory::Tier::GPU) {
 85	    auto device_id  = _memory_space->get_device_id();
 86	    per_thread_init = [device_id]() noexcept {
 87	      // Pin each worker to its GPU; silent failure leaks downgrade memcpys
 88	      // across contexts. Lambda is noexcept, so check inline.
 89	      cudaError_t err = cudaSetDevice(device_id);
 90	      if (err != cudaSuccess) {
 91	        SIRIUS_LOG_ERROR("downgrade_executor per-thread init: cudaSetDevice({}) failed: {}",
 92	                         device_id,
 93	                         cudaGetErrorString(err));
 94	      }
 95	    };
 96	  }
 97	
 98	  _pool = std::make_unique<exec::bounded_thread_pool>(_config.thread_pool.num_threads,
 99	                                                      _config.thread_pool.thread_name_prefix,
100	                                                      _config.thread_pool.cpu_affinity_list,
101	                                                      std::move(per_thread_init));
102	
103	  _processing_thread = std::thread(&downgrade_executor::processing_loop, this);
104	
105	  if (_memory_space && _config.monitor_period > std::chrono::milliseconds::zero()) {
106	    _monitor_thread = std::thread(&downgrade_executor::monitor_loop, this);
107	  }
108	}
109	
110	void downgrade_executor::stop()
111	{
112	  bool expected = true;
113	  if (!_running.compare_exchange_strong(expected, false)) { return; }
114	
115	  _pool->interrupt();
116	  _request_queue.interrupt();
117	  _monitor_cv.notify_one();
118	
119	  if (_monitor_thread.joinable()) { _monitor_thread.join(); }
120	  if (_processing_thread.joinable()) { _processing_thread.join(); }
121	
122	  _pool->wait_all();
123	  cancel_pending_requests();
124	  _pool->stop();
125	  _pool.reset();
126	  _stream_pool.reset();
127	}
128	
129	void downgrade_executor::drain()
130	{
131	  _pool->interrupt();
132	  _request_queue.interrupt();
133	
134	  if (_processing_thread.joinable()) { _processing_thread.join(); }
135	
136	  _pool->wait_all();
137	  cancel_pending_requests();
138	  _pool->resume();
139	  _request_queue.reactivate();
140	
141	  _processing_thread = std::thread(&downgrade_executor::processing_loop, this);
142	}
143	
144	void downgrade_executor::processing_loop()
145	{
146	  while (_running.load()) {
147	    auto request = _request_queue.pop();
148	    if (!request) break;  // interrupted
149	
150	    auto& req = request;
151	
152	    auto t_start = std::chrono::steady_clock::now();
153	
154	    // Per-source tracking (repos vs pipeline_queue)
155	    struct source_stats {
156	      std::atomic<size_t> batches{0};
157	      std::atomic<size_t> bytes{0};
158	    };
159	    source_stats repo_stats, pipeline_queue_stats;
160	
161	    // Per-target-tier tracking (host vs disk)
162	    struct target_tier_stats {
163	      std::atomic<size_t> batches{0};
164	      std::atomic<size_t> bytes{0};
165	    };
166	    target_tier_stats host_target_stats, disk_target_stats;
167	
168	    // Resolve the source memory space for filtering candidates
169	    auto* source_space = _reservation_manager.get_memory_space(_space_id.tier, _space_id.device_id);
170	
171	    // Build target spaces list: for GPU->HOST downgrade, target is HOST tier followed by DISK tier.
172	    // NUMA preference (from downgrade_executor_config, v1.0 dd86dd0 intent re-authored on the
173	    // post-#637 architecture): if preferred_numa_node is set, stable_partition the matching HOST
174	    // space(s) to the front of target_spaces so cand->convert() tries the NUMA-local space first.
175	    std::vector<const cucascade::memory::memory_space*> target_spaces;
176	    if (_space_id.tier == cucascade::memory::Tier::GPU) {
177	      auto host_span =
178	        _reservation_manager.get_memory_spaces_for_tier(cucascade::memory::Tier::HOST);
179	      // Copy span -> vector before reordering: the span is a view into the manager's
180	      // internal storage, and stable_partition would otherwise mutate it in place.
181	      std::vector<const cucascade::memory::memory_space*> host_spaces(host_span.begin(),
182	                                                                      host_span.end());
183	      if (auto pref = _config.preferred_numa_node; pref.has_value()) {
184	        std::stable_partition(host_spaces.begin(),
185	                              host_spaces.end(),
186	                              [pref_numa = *pref](const cucascade::memory::memory_space* s) {
187	                                return s != nullptr &&
188	                                       static_cast<int>(s->get_device_id()) == pref_numa;
189	                              });
190	      }
191	      for (auto* hs : host_spaces) {
192	        target_spaces.push_back(hs);
193	      }
194	    }
195	    size_t host_end_idx = target_spaces.size();
196	    auto disk_spaces =
197	      _reservation_manager.get_memory_spaces_for_tier(cucascade::memory::Tier::DISK);
198	    bool disk_not_configured = disk_spaces.empty();
199	    for (auto* ds : disk_spaces) {
200	      target_spaces.push_back(ds);
201	    }
202	
203	    // === TIER 1: Data repositories ===
204	    // Memory pressure is a global condition, so candidates are drawn from EVERY in-flight
205	    // query: outer loop DESCENDING by query id (newest query first), inner loop in
206	    // get_repositories() order — ascending {operator_id, port_id} — with early stop once the
207	    // reservation is satisfied. Operator ids restart at 0 per query, so ordering is
208	    // (query id, operator id) rather than a single global counter.
209	    //
210	    // Newest-first is the fairness policy: query ids are monotonic, so the newest query is the
211	    // one that has made the least progress, and spilling it costs the least re-materialization
212	    // work. It also keeps the oldest query's working set resident so it can finish and release
213	    // its memory, which is what actually relieves the pressure — spilling the oldest query
214	    // instead would slow down the query closest to completing while newer arrivals keep
215	    // allocating. This makes the pressure response FIFO: earliest queries keep execution
216	    // priority, latest queries pay for the memory.
217	    //
218	    // get_all() returns ascending by query id, so this iterates the snapshot in reverse.
219	    // get_all_convertible() snapshots eligible batches once per repo so a batch isn't
220	    // re-scanned before leaving idle. Managers are held by shared_ptr for the duration of the
221	    // sweep, so a query ending concurrently cannot pull one out from under this loop.
222	    bool pool_interrupted = false;
223	    auto const managers   = _data_repo_registry.get_all();
224	    for (auto const& manager : std::views::reverse(managers)) {
225	      if (req->satisfied.load() || pool_interrupted) break;
226	      auto repos = manager->get_repositories();
227	      for (auto* repo : repos) {
228	        if (req->satisfied.load()) break;
229	
230	        convertible_data_batch_provider provider(repo);
231	        auto candidates = provider.get_all_convertible(
232	          source_space, /*front_to_back=*/false, /*ignore_subscribed=*/true);
233	        for (auto& candidate : candidates) {
234	          if (req->satisfied.load()) break;
235	
236	          auto candidate_bytes = candidate->bytes_in_space(source_space);
237	
238	          auto slot = _pool->reserve();
239	          if (!slot) {
240	            pool_interrupted = true;
241	            break;
242	          }
243	
244	          // Re-check after reserve() returns -- the previous candidate's worker may
245	          // have set satisfied while we were blocked waiting for a thread slot.
246	          if (req->satisfied.load()) break;
247	
248	          auto exc_stream = _stream_pool->acquire_stream(
249	            cucascade::memory::exclusive_stream_pool::stream_acquire_policy::GROW);
250	
251	          _pool->dispatch(
252	            std::move(slot),
253	            [cand       = std::move(candidate),
254	             req_ptr    = req.get(),
255	             &res_mgr   = _reservation_manager,
256	             &targets   = target_spaces,
257	             exc_stream = std::move(exc_stream),
258	             candidate_bytes,
259	             host_end_idx,
260	             &repo_stats,
261	             &host_target_stats,
262	             &disk_target_stats]() mutable {
263	              try {
264	                auto result = cand->convert(targets, exc_stream, res_mgr, false);
265	                if (result) {
266	                  req_ptr->bytes_freed.fetch_add(candidate_bytes, std::memory_order_relaxed);
267	                  req_ptr->batches_downgraded.fetch_add(1, std::memory_order_relaxed);
268	                  repo_stats.batches.fetch_add(1, std::memory_order_relaxed);
269	                  repo_stats.bytes.fetch_add(candidate_bytes, std::memory_order_relaxed);
270	                  for (size_t i = 0; i < result->size(); ++i) {
271	                    if ((*result)[i] == 0) continue;
272	                    if (i < host_end_idx) {
273	                      host_target_stats.batches.fetch_add(1, std::memory_order_relaxed);
274	                      host_target_stats.bytes.fetch_add((*result)[i], std::memory_order_relaxed);
275	                    } else {
276	                      disk_target_stats.batches.fetch_add(1, std::memory_order_relaxed);
277	                      disk_target_stats.bytes.fetch_add((*result)[i], std::memory_order_relaxed);
278	                    }
279	                  }
280	                  if (req_ptr->predicate && req_ptr->predicate()) {
281	                    req_ptr->satisfied.store(true);
282	                  }
283	                }
284	              } catch (const std::exception& e) {
285	                SIRIUS_LOG_ERROR("[downgrade] convert failed from data repository: {}", e.what());
286	              }
287	            });
288	        }
289	        if (pool_interrupted) break;
290	      }
291	    }
292	
293	    // === TIER 2: task_scheduler task queue ===
294	    if (!req->satisfied.load() && _pipeline_task_queue) {
295	      size_t max_tasks_to_convert = _pipeline_task_queue->size();
296	      size_t tasks_converted      = 0;
297	      convertible_gpu_pipeline_task_provider pipeline_provider(*_pipeline_task_queue);
298	      while (!req->satisfied.load() && tasks_converted < max_tasks_to_convert) {
299	        auto candidate =
300	          pipeline_provider.get_next_convertible(source_space, /*front_to_back=*/false);
301	        if (!candidate) break;
302	        tasks_converted++;
303	
304	        auto candidate_bytes = candidate->bytes_in_space(source_space);
305	
306	        auto slot = _pool->reserve();
307	        if (!slot) break;  // interrupted
308	
309	        if (req->satisfied.load()) break;
310	
311	        auto exc_stream = _stream_pool->acquire_stream(
312	          cucascade::memory::exclusive_stream_pool::stream_acquire_policy::GROW);
313	
314	        _pool->dispatch(
315	          std::move(slot),
316	          [cand       = std::move(candidate),
317	           req_ptr    = req.get(),
318	           &res_mgr   = _reservation_manager,
319	           &targets   = target_spaces,
320	           exc_stream = std::move(exc_stream),
321	           candidate_bytes,
322	           host_end_idx,
323	           &pipeline_queue_stats,
324	           &host_target_stats,
325	           &disk_target_stats]() mutable {
326	            try {
327	              auto result = cand->convert(targets, exc_stream, res_mgr, false);
328	              if (result) {
329	                req_ptr->bytes_freed.fetch_add(candidate_bytes, std::memory_order_relaxed);
330	                req_ptr->batches_downgraded.fetch_add(1, std::memory_order_relaxed);
331	                pipeline_queue_stats.batches.fetch_add(1, std::memory_order_relaxed);
332	                pipeline_queue_stats.bytes.fetch_add(candidate_bytes, std::memory_order_relaxed);
333	                for (size_t i = 0; i < result->size(); ++i) {
334	                  if ((*result)[i] == 0) continue;
335	                  if (i < host_end_idx) {
336	                    host_target_stats.batches.fetch_add(1, std::memory_order_relaxed);
337	                    host_target_stats.bytes.fetch_add((*result)[i], std::memory_order_relaxed);
338	                  } else {
339	                    disk_target_stats.batches.fetch_add(1, std::memory_order_relaxed);
340	                    disk_target_stats.bytes.fetch_add((*result)[i], std::memory_order_relaxed);
341	                  }
342	                }
343	                if (req_ptr->predicate && req_ptr->predicate()) { req_ptr->satisfied.store(true); }
344	              }
345	            } catch (const std::exception& e) {
346	              SIRIUS_LOG_ERROR("[downgrade] convert failed from task queue: {}", e.what());
347	            }
348	          });
349	      }
350	    }
351	
352	    // Wait for all in-flight work to finish (predicate also checked in workers)
353	    _pool->wait_all();
354	
355	    // Monitor requests are gated by has_viable_downgrade_target() and warn once per stall episode
356	    // in monitor_loop(); only warn here for one-shot (external) requests to avoid log spam.
357	    if (disk_not_configured && !req->satisfied.load() && !req->is_monitor_request) {
358	      SIRIUS_LOG_WARN(
359	        "[downgrade] [{}] downgrade request not satisfied and disk memory space is not configured; "
360	        "data cannot be spilled to disk. Consider configuring a disk memory space to enable "
361	        "spilling.",
362	        _source_label);
363	    }
364	
365	    // === Logging ===
366	    auto total_bytes   = req->bytes_freed.load(std::memory_order_relaxed);
367	    auto total_batches = req->batches_downgraded.load(std::memory_order_relaxed);
368	    auto duration_ms =
369	      std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - t_start).count();
370	    double throughput_mbs =
371	      (duration_ms > 0.0) ? (total_bytes / (1024.0 * 1024.0)) / (duration_ms / 1000.0) : 0.0;
372	    std::string request_label = req->is_monitor_request ? "monitor " : "";
373	    if (req->is_monitor_request) {
374	      _monitor_request_enqueued.store(false, std::memory_order_relaxed);
375	    }
376	
377	    SIRIUS_LOG_DEBUG(
378	      "[downgrade] [{}] request {}done: {} batches, {} bytes in {:.2f} ms ({:.1f} MB/s) | "
379	      "repos: {}/{} batches/bytes, pipeline_queue: {}/{} | "
380	      "to_host: {}/{} batches/bytes, to_disk: {}/{} batches/bytes",
381	      _source_label,
382	      request_label,
383	      total_batches,
384	      total_bytes,
385	      duration_ms,
386	      throughput_mbs,
387	      repo_stats.batches.load(std::memory_order_relaxed),
388	      repo_stats.bytes.load(std::memory_order_relaxed),
389	      pipeline_queue_stats.batches.load(std::memory_order_relaxed),
390	      pipeline_queue_stats.bytes.load(std::memory_order_relaxed),
391	      host_target_stats.batches.load(std::memory_order_relaxed),
392	      host_target_stats.bytes.load(std::memory_order_relaxed),
393	      disk_target_stats.batches.load(std::memory_order_relaxed),
394	      disk_target_stats.bytes.load(std::memory_order_relaxed));
395	
396	    // Fulfill the promise
397	    req->result.set_value(total_bytes);
398	  }
