405	
406	bool downgrade_executor::has_viable_downgrade_target() const
407	{
408	  using cucascade::memory::Tier;
409	
410	  // DISK is an effectively unbounded sink and a valid target for any source tier.
411	  if (has_disk_tier()) { return true; }
412	
413	  // Without a disk tier, only a GPU source has a lower tier to downgrade to (HOST). processing_loop
414	  // only adds HOST target spaces when the source is GPU, so a HOST (or other) source has no target
415	  // at all and can never free anything -- it must back off rather than re-fire.
416	  if (_space_id.tier != Tier::GPU) { return false; }
417	
418	  // GPU source, no disk: viable iff some HOST space can currently accept a reservation. Probe with
419	  // exactly the operation a downgrade performs -- make_reservation_or_null of one chunk, released
420	  // immediately (RAII). This is the ground truth: HOST reserve() is bounded by _allocated_bytes,
421	  // which reflects BOTH live reservations AND already-stored downgraded data, so neither
422	  // get_total_reserved_memory nor get_available_memory alone captures whether a downgrade can land.
423	  // (The chunk-sized probe matches the chunked allocator's rounding; a sub-chunk request would
424	  // succeed against a remainder that no real batch could use.)
425	  for (const auto* hs : _reservation_manager.get_memory_spaces_for_tier(Tier::HOST)) {
426	    if (!hs) { continue; }
427	    // The manager owns these spaces mutably; the span just exposes them as const. make_reservation
428	    // mutates accounting, so we need a mutable handle.
429	    auto* host         = const_cast<cucascade::memory::memory_space*>(hs);
430	    size_t probe_bytes = 1;
431	    if (const auto* chunked = host->get_chunked_resource_info()) {
432	      probe_bytes = chunked->max_chunk_bytes();
433	    }
434	    // A chunk larger than this space's reservation limit can never be reserved (the HOST allocator
435	    // throws on an over-limit request), so such a space cannot accept a downgrade -- skip it. The
436	    // try/catch is belt-and-suspenders: this runs on the monitor thread, which must never throw.
437	    if (probe_bytes > host->get_max_memory()) { continue; }
438	    try {
439	      if (auto probe = host->make_reservation_or_null(probe_bytes)) { return true; }
440	    } catch (const std::exception& e) {
441	      SIRIUS_LOG_DEBUG("[downgrade] [{}] host viability probe failed: {}", _source_label, e.what());
442	    }
443	  }
444	  return false;
445	}
446	
447	void downgrade_executor::monitor_loop()
448	{
449	  using namespace std::chrono_literals;
450	
451	  // Monitor-thread-local; throttles the back-off warning to once per stall episode.
452	  bool backed_off = false;
453	
454	  while (_running.load()) {
455	    if (_memory_space && _memory_space->should_downgrade_memory() &&
456	        !_monitor_request_enqueued.load(std::memory_order_relaxed)) {
457	      // Stateless viability gate: only issue a downgrade request when one could plausibly free
458	      // memory. When idle GPU batches' only lower tier is a full HOST and no DISK is configured,
459	      // re-firing would just re-scan every repository and the task queue, free nothing, and spam
460	      // the log every monitor_period (~100x/s by default) forever. Skipping the cycle backs
461	      // off cleanly; because this is re-checked every cycle the monitor resumes the instant host
462	      // frees or pressure drops -- there is no latched state to get wedged on.
463	      if (has_viable_downgrade_target()) {
464	        backed_off    = false;
465	        size_t amount = _memory_space->get_amount_to_downgrade();
466	        if (amount > 0) {
467	          auto req                = std::make_unique<downgrade_request>();
468	          req->is_monitor_request = true;
469	          req->predicate          = [&freed = req->bytes_freed, amount]() {
470	            return freed.load(std::memory_order_relaxed) >= amount;
471	          };
472	          _monitor_requests_issued.fetch_add(1, std::memory_order_relaxed);
473	          _monitor_request_enqueued.store(true, std::memory_order_relaxed);
474	          // Fire-and-forget: monitor does not wait for the result
475	          _request_queue.push(std::move(req));
476	        }
477	      } else if (!backed_off) {
478	        SIRIUS_LOG_WARN(
479	          "[downgrade] [{}] memory pressure but no viable downgrade target (host full, no disk "
480	          "configured); backing off until memory is released. Consider configuring a disk memory "
481	          "space to enable spilling.",
482	          _source_label);
483	        backed_off = true;
484	      }
485	    } else {
486	      // Pressure gone -- reset so the next stall episode warns again.
487	      backed_off = false;
488	    }
489	    // Wait for the monitor period, but wake immediately on shutdown.
490	    std::unique_lock<std::mutex> lock(_monitor_cv_mutex);
491	    _monitor_cv.wait_for(
492	      lock, _config.monitor_period, [this]() { return !_running.load(std::memory_order_relaxed); });
493	  }
494	}
