516	std::future<size_t> downgrade_executor::request_free_memory(size_t bytes)
517	{
518	  auto req       = std::make_unique<downgrade_request>();
519	  req->predicate = [&freed = req->bytes_freed, bytes]() {
520	    return freed.load(std::memory_order_relaxed) >= bytes;
521	  };
522	  auto future = req->result.get_future();
523	  if (!_request_queue.push(std::move(req))) {
524	    SIRIUS_LOG_WARN(
525	      "[downgrade] request_free_memory: queue inactive, dropping request for {} bytes", bytes);
526	  }
527	  return future;
528	}
